<?php
 namespace QQWorld\Sales\Model\Order\Email; use QQWorld\Sales\Model\Order; use QQWorld\Sales\Model\Order\Email\Container\IdentityInterface; use QQWorld\Sales\Model\Order\Email\Container\Template; use QQWorld\Sales\Model\Order\Address\Renderer; abstract class Sender { protected $senderBuilderFactory; protected $templateContainer; protected $identityContainer; protected $logger; protected $addressRenderer; public function __construct( Template $templateContainer, IdentityInterface $identityContainer, \QQWorld\Sales\Model\Order\Email\SenderBuilderFactory $senderBuilderFactory, \Psr\Log\LoggerInterface $logger, Renderer $addressRenderer ) { $this->templateContainer = $templateContainer; $this->identityContainer = $identityContainer; $this->senderBuilderFactory = $senderBuilderFactory; $this->logger = $logger; $this->addressRenderer = $addressRenderer; } protected function checkAndSend(Order $order) { $this->identityContainer->setStore($order->getStore()); if (!$this->identityContainer->isEnabled()) { return false; } $this->prepareTemplate($order); $sender = $this->getSender(); try { $sender->send(); $sender->sendCopyTo(); } catch (\Exception $e) { $this->logger->error($e->getMessage()); } return true; } protected function prepareTemplate(Order $order) { $this->templateContainer->setTemplateOptions($this->getTemplateOptions()); if ($order->getCustomerIsGuest()) { $templateId = $this->identityContainer->getGuestTemplateId(); $customerName = $order->getBillingAddress()->getName(); } else { $templateId = $this->identityContainer->getTemplateId(); $customerName = $order->getCustomerName(); } $this->identityContainer->setCustomerName($customerName); $this->identityContainer->setCustomerEmail($order->getCustomerEmail()); $this->templateContainer->setTemplateId($templateId); } protected function getSender() { return $this->senderBuilderFactory->create( [ 'templateContainer' => $this->templateContainer, 'identityContainer' => $this->identityContainer, ] ); } protected function getTemplateOptions() { return [ 'area' => \QQWorld\Framework\App\Area::AREA_FRONTEND, 'store' => $this->identityContainer->getStore()->getStoreId() ]; } protected function getFormattedShippingAddress($order) { return $order->getIsVirtual() ? null : $this->addressRenderer->format($order->getShippingAddress(), 'html'); } protected function getFormattedBillingAddress($order) { return $this->addressRenderer->format($order->getBillingAddress(), 'html'); } } 